parameters.jsCode:
// Decide what to DO with this reply, using both the intent category and the
// conversation_type. ACCEPT/DECLINE only mean something inside a cascade or a
// confirmation flow -> map them to the right slot RPC. Everything ambiguous or
// human-worthy falls through to escalate / generic AI reply.
const parsed = JSON.parse($('Classify intent (Groq 8B)').item.json.choices[0].message.content);
let category = (parsed.category || 'UNCLEAR').toUpperCase();
// Small classifiers can hallucinate FRUSTRATED on ordinary short replies (e.g.
// a bare name during placeholder-name capture -> reproduced live on "miguel
// snatos"). Require keyword corroboration before trusting the label; the
// documented design is hybrid (keyword shortcut + AI), not AI-only. Without
// evidence, fall through as UNCLEAR so the richer-context assist branch
// decides instead of escalating blind.
if (category === 'FRUSTRATED') {
  const raw = ($('agent_inbound_batch').item.json.joined_body || '').toLowerCase();
  const hasEvidence = /porra|merda|caralho|foda-se|burro|idiota|estúpid|raios|inútil|lixo|ridículo|chatead|irritad|fart[oa]|cansad[oa] disto|p[ée]ssimo|horr[íi]vel|que se lixe|!!|\?!/.test(raw);
  if (!hasEvidence) category = 'UNCLEAR';
}
const lang = parsed.lang || 'pt';
const ctx = $('agent_context').item.json;
const convType = ctx.conversation_type;
const conversation_id = ctx.conversation_id;

// Booking-choice short-circuit: if we previously offered slots, this reply is a choice.
const offered_ids = ctx.offered_slot_ids || [];
if (offered_ids && offered_ids.length) {
  return { json: { category, lang, action: 'booking_choice', escalate_category: null, rpc: null, conversation_id } };
}

// A pending cancel-or-reschedule nudge takes the next reply as its answer.
if (ctx.cancel_pending) {
  return { json: { category, lang, action: 'cancel_choice', escalate_category: null, rpc: null, conversation_id } };
}

const escalateMap = { FRUSTRATED: 'complaint', INSURANCE: 'insurance_issue' };
let action = 'reply';          // reply = generic AI answer (default)
let escalate_category = null;  // set when action = escalate
let rpc = null;                // slot RPC to call when action = rpc

if (category in escalateMap) {
  action = 'escalate';
  escalate_category = escalateMap[category];
} else if (convType === 'slot_cascade') {
  if (category === 'ACCEPT')  { action = 'rpc'; rpc = 'cascade_respond_accept'; }
  else if (category === 'DECLINE') { action = 'rpc'; rpc = 'cascade_respond_decline'; }
  // UNCLEAR on a cascade -> fall through to a generic AI nudge (SIM/NÃO?).
} else if (convType === 'confirmation') {
  if (category === 'ACCEPT')  { action = 'rpc'; rpc = 'confirmation_confirm'; }
  else if (category === 'DECLINE') { action = 'rpc'; rpc = 'confirmation_decline'; }
}

return { json: { category, lang, action, escalate_category, rpc, conversation_id } };

// Compose a short, deterministic acknowledgement for the person who just
// replied (no Groq call needed — these are fixed outcomes), and decide whether
// we must advance the cascade to the next candidate.
//   - cascade DECLINE: ack + advance (re-post the freed slot to WF-B).
//   - cascade ACCEPT / confirmation ACCEPT / confirmation DECLINE: ack only.
//     (an accepted cascade or a declined confirmation flips a slot's status,
//      which the DB trigger turns into a fresh cascade automatically.)
const route = $('Route').item.json;
const res = $json;                 // RPC result envelope
const en = (route.lang || 'pt') === 'en';
const rpc = route.rpc;
const status = res && res.status;

let ack = '';
let advance_cascade = false;
let slot_id = null;

if (rpc === 'cascade_respond_accept') {
  ack = status === 'accepted'
    ? (en ? 'Perfect! Your appointment has been rescheduled. See you soon.' : 'Perfeito! A sua consulta foi remarcada. Até breve.')
    : (en ? 'That slot has already been taken — thank you anyway.' : 'Essa vaga já foi preenchida, obrigado à mesma.');
} else if (rpc === 'cascade_respond_decline') {
  ack = en ? 'No problem, thank you for letting us know.' : 'Sem problema, obrigado pela resposta.';
  advance_cascade = true;
  slot_id = res && res.slot_id;
} else if (rpc === 'confirmation_confirm') {
  ack = en ? 'Thank you, your appointment is confirmed.' : 'Obrigado, a sua consulta está confirmada.';
} else if (rpc === 'confirmation_decline') {
  ack = en ? 'Thank you for letting us know. We will free up the slot.' : 'Obrigado por avisar. Vamos libertar o horário.';
}

return { json: { conversation_id: route.conversation_id, ack_body: ack, advance_cascade, slot_id } };

const ctx = $('agent_context').item.json;
const route = $('Route').item.json;
const clinic = ctx.clinic_name || 'a clínica';
const convType = ctx.conversation_type || '';
const patient = (ctx.patient && ctx.patient.name) || '';
const firstName = (patient && !/^Novo contacto/.test(patient)) ? patient.split(' ')[0] : '';
const messages = ctx.messages || [];
const zone='Europe/Lisbon';
const now = DateTime.now().setZone(zone);
const today = now.toFormat('yyyy-MM-dd');
const weekday = now.setLocale('pt').toFormat('cccc');
const system = 'É rececionista da ' + clinic + ', em Portugal. Hoje é ' + today + ' (' + weekday + '), fuso Europe/Lisbon. O paciente escreveu algo que não é um sim/não claro numa conversa do tipo "' + convType + '". '
  + 'Decida UMA ação e responda em JSON estrito: {"action":"reply"|"offer"|"escalate"|"cancel_request","message":"...","reason":"...","category":"booking_request"|"conversation_takeover","date":"YYYY-MM-DD"|null,"from":"HH:MM"|null,"to":"HH:MM"|null}.\n'
  + '- Se o paciente quer remarcar, marcar, antecipar, adiar ou mudar para outra data/hora E já indicou nesta mensagem (ou numa anterior, ainda por atender) alguma preferência de dia, hora ou período: action="offer" (vamos procurar vagas). "message" e "reason" vazios. Preencha date/from/to com o que ele indicou:\n'
  + '   • dia ("terça dia 18", "amanhã", "para a semana") -> date (resolva para uma data real YYYY-MM-DD);\n'
  + '   • hora aproximada ("por volta das 16h", "às 15h") -> from=essa hora (HH:MM), to=null;\n'
  + '   • período: "de manhã" -> from=08:00,to=13:00; "à tarde" -> from=13:00,to=19:00; "ao fim do dia"/"fim da tarde" -> from=16:00,to=19:00; "hora de almoço" -> from=12:00,to=14:00;\n'
  + '- Se o paciente quer marcar/remarcar mas AINDA NÃO indicou nenhuma preferência de dia, hora ou período (ex.: "queria marcar uma consulta", "gostava de remarcar"): action="reply"; "message" pergunta, de forma simpática e breve, que dia e que altura do dia lhe dá mais jeito — NÃO sugira nenhum horário nem vaga concreta, apenas pergunte; date/from/to a null.\n'
  + '- Se o paciente disser que quer cancelar, desmarcar ou anular a consulta e NÃO pedir nem aceitar remarcar para outra data: action="cancel_request"; "message" e "reason" vazios; date/from/to a null. Se a mesma mensagem também mencionar uma data/hora nova ou pedir para remarcar, trate como remarcação ("offer"), não como cancelamento.\n'
  + '- Pergunta clínica/médica, sintomas, medicação, ou algo incerto que exija um humano: action="escalate", category="conversation_takeover"; "reason" resume; "message" vazio.\n'
  + '- Pergunta simples de logística sobre a marcação (médico, hora, local): action="reply", "message" curta e cordial.\n'
  + 'Entre "offer" e "escalate" para remarcações, prefira "offer". Nunca dê conselhos médicos nem invente horas. Português europeu formal ("você"), ou inglês se o paciente escreveu em inglês. '
  + (firstName ? ('Trate por "' + firstName + '". ') : '')
  + 'NÃO escreva nada sobre STOP; isso é tratado automaticamente.';
const user = 'Conversa até agora: ' + JSON.stringify(messages);
return { json: { conversation_id: route.conversation_id, system_prompt: system, user_prompt: user } };

const parsed = JSON.parse($json.choices[0].message.content);
const conv = $('Build assist prompt').item.json.conversation_id;
let action = String(parsed.action || 'reply').toLowerCase();
if (!['reply','offer','escalate','cancel_request'].includes(action)) action = 'reply';
let category = String(parsed.category || 'conversation_takeover');
if (category !== 'booking_request' && category !== 'conversation_takeover') category = 'conversation_takeover';
let message = parsed.message || '';

// Continuity of care: default every fresh offer search to the patient's
// assigned doctor, unless they explicitly named someone else in this
// message -- deterministic surname match against the real roster (never an
// LLM guess, per the FRUSTRATED/wrong-doctor lessons learned live today).
const ctx = $('agent_context').item.json;
const doctors = ctx.doctors || [];
const raw = ($('agent_inbound_batch').item.json.joined_body || '').toLowerCase();
let requested_doctor_id = null;
for (const d of doctors) {
  const surname = d.name.trim().split(/\s+/).pop().toLowerCase();
  if (surname && raw.includes(surname)) { requested_doctor_id = d.id; break; }
}
const primary_doctor_id = (ctx.patient && ctx.patient.primary_doctor_id) || null;
const doctor_id = requested_doctor_id || primary_doctor_id || null;
const lock_doctor = !!requested_doctor_id;
const doctor_source = requested_doctor_id ? 'requested' : (primary_doctor_id ? 'primary' : 'none');

return { json: { conversation_id: conv, action, category, message, reason: parsed.reason || 'Pedido do paciente', date: parsed.date || null, from: parsed.from || null, to: parsed.to || null, doctor_id, lock_doctor, doctor_source } };

