const res = $json; // find_availability_window result
const ctx = $('agent_context').item.json;
const conv = $('Route assist').item.json.conversation_id;
const zone='Europe/Lisbon';
const fmtTime=(iso)=>DateTime.fromISO(iso).setZone(zone).toFormat('HH:mm');
const dayWord=(iso)=>{const d=DateTime.fromISO(iso).setZone(zone).startOf('day');const t=DateTime.now().setZone(zone).startOf('day');const diff=Math.round(d.diff(t,'days').days);return diff===0?'hoje':(diff===1?'amanhã':DateTime.fromISO(iso).setZone(zone).toFormat('dd/MM'));};
const fmt=(iso)=>dayWord(iso)+' às '+fmtTime(iso);
if (!res || res.status!=='options' || !Array.isArray(res.slots) || res.slots.length===0) {
  return { json: { conversation_id: conv, action:'escalate', reason:'Pedido de marcação, sem vagas disponíveis para oferecer' } };
}
const clinic = ctx.clinic_name || 'a clínica';
const patient = (ctx.patient && ctx.patient.name) || '';
const firstName = (patient && !/^Novo contacto/.test(patient)) ? patient.split(' ')[0] : '';
const single = res.slots.length === 1;
const substitute = res.doctor_unavailable === true;
const primaryName = (ctx.patient && ctx.patient.primary_doctor_name) || '';
let facts;
if (res.requested && single) {
  const s=res.slots[0];
  facts = res.exact
    ? ('O paciente pediu as '+res.requested+' e HÁ vaga EXATAMENTE a essa hora: '+fmt(s.start_time)+(s.doctor_name?(' com '+s.doctor_name):'')+'. É a hora que ele pediu, NÃO uma aproximação. Objetivo: confirmar com simpatia que temos vaga à hora que pediu e perguntar se pode ser.')
    : ('O paciente pediu por volta das '+res.requested+', mas não há vaga a essa hora exata. A vaga livre mais próxima é '+fmt(s.start_time)+(s.doctor_name?(' com '+s.doctor_name):'')+'. Objetivo: dizer com simpatia que a hora pedida não está livre e propor esta, a mais próxima.');
} else {
  facts = 'Vagas disponíveis (todas reais, use tal e qual): '
    + res.slots.map(s => fmt(s.start_time)+(s.doctor_name?(' com '+s.doctor_name):'')).join('; ')
    + '. Objetivo: apresentar estas opções de forma simpática e perguntar qual prefere.';
}
if (substitute) {
  facts = (primaryName ? ('O médico/médica habitual do paciente, '+primaryName+', não tem vaga disponível nesse período. ') : 'O médico/médica habitual do paciente não tem vaga disponível nesse período. ')
    + facts
    + ' Objetivo adicional: deixar claro que é uma substituição só para desta vez (não muda o médico habitual do paciente) e pedir confirmação antes de avançar.';
}
const closeRule = single
  ? 'Há apenas UMA vaga: termine com uma pergunta natural de confirmação (ex.: "fica-lhe bem?", "pode ser?", "confirmo?"). NÃO pergunte "qual prefere" nem "qual lhe dá mais jeito". '
  : 'Há várias vagas: convide a escolher de forma natural (ex.: "qual lhe dá mais jeito?", "qual prefere?"). ';
const system = 'É rececionista da '+clinic+', em Portugal, e escreve como uma pessoa real: cordial, natural e breve. '
  + 'Português europeu formal ("você"), ou inglês se o paciente escreveu em inglês. Nunca se apresenta nem inventa nomes. '
  + (firstName ? ('Trate o paciente por "'+firstName+'". ') : '')
  + 'Escreva UMA mensagem curta em linguagem corrida (NUNCA use listas numeradas, "1)", "2)", nem bullets). '
  + closeRule
  + 'Não peça um formato rígido tipo "responda SIM ou NÃO" nem para responder com um número. '
  + 'Se os factos disserem que há vaga À HORA pedida, confirme que é exatamente essa hora; NUNCA escreva "perto", "próximo", "por volta" nem "aproximado". Só fale numa vaga "mais próxima" se os factos disserem que a hora pedida NÃO está disponível. '
  + (substitute ? 'Os factos indicam que é uma substituição pontual do médico habitual: mencione isso com simpatia (ex.: "só desta vez", "excecionalmente") e deixe claro que não muda o médico habitual do paciente. ' : '')
  + 'REGRA ABSOLUTA: copie horas, datas e nomes EXATAMENTE como aparecem nos factos; nunca invente nem altere um número. '
  + 'NÃO escreva nenhuma linha sobre STOP nem sobre cancelar subscrição; isso é acrescentado automaticamente quando necessário. '
  + 'Responda APENAS com o texto da mensagem.';
return { json: { conversation_id: conv, action:'humanize', system_prompt: system, user_prompt: facts } };

const ctx = $('agent_context').item.json;
const offered = ctx.offered_slots || [];
const messages = ctx.messages || [];
const pm = messages.filter(m => m.sender_type === 'patient');
const last = $('agent_inbound_batch').item.json.joined_body || (pm[pm.length - 1] || {}).body || '';
const zone = 'Europe/Lisbon';
const now = DateTime.now().setZone(zone);
const today = now.toFormat('yyyy-MM-dd');
const weekday = now.setLocale('pt').toFormat('cccc');
const fmt = (iso) => { const d = DateTime.fromISO(iso).setZone(zone); const t0 = now.startOf('day'); const diff = Math.round(d.startOf('day').diff(t0,'days').days); const day = diff===0?'hoje':(diff===1?'amanhã':d.toFormat('dd/MM')); return day + ' às ' + d.toFormat('HH:mm'); };
const list = offered.map((s,i) => (i+1) + ') ' + fmt(s.start_time) + (s.doctor_name?(' com '+s.doctor_name):'') + ' [slot_id=' + s.slot_id + ']').join('\n');
const single = offered.length === 1;
const system = 'Hoje é ' + today + ' (' + weekday + '), fuso Europe/Lisbon. O paciente respondeu a uma oferta de ' + (single ? 'uma vaga mais cedo' : 'vagas') + ':\n' + list + '\n\n'
  + 'Interprete a última mensagem e devolva JSON estrito {"slot_id":"<id>"|null,"decline":true|false,"other_time":true|false,"date":"YYYY-MM-DD"|null,"from":"HH:MM"|null,"to":"HH:MM"|null}.\n'
  + (single
      ? '- Se concordar (ex.: "sim", "pode ser", "quero", "aceito", "claro"), devolva o slot_id da vaga.\n'
      : '- Se escolher uma opção (por número, hora ou dia), devolva o slot_id correspondente.\n')
  + '- Se PEDIR outro horário/dia que NÃO está na lista (ex.: "pode ser às 15h?", "tem algo quinta de manhã?", "só à tarde", "e à tarde?"), devolva other_time=true, slot_id=null, decline=false, e preencha date/from/to: dia -> date (resolva "amanhã"/"quinta"/"dia 20" para YYYY-MM-DD); hora aproximada ("por volta das 16h","às 15h") -> from=essa hora, to=null; "de manhã" -> from=08:00,to=13:00; "à tarde" -> from=13:00,to=19:00; "ao fim do dia"/"fim da tarde" -> from=16:00,to=19:00; null no que não indicar.\n'
  + '- Se recusar ou quiser manter a marcação atual (ex.: "não", "deixa estar", "fico como está"), devolva decline=true.\n'
  + '- Se não for claro, devolva tudo null/false.\nUse APENAS os slot_id listados; nunca invente slot_id.';
const user = 'Mensagem do paciente: ' + JSON.stringify(last);
return { json: { conversation_id: ctx.conversation_id, system_prompt: system, user_prompt: user } };

const parsed = JSON.parse($json.choices[0].message.content);
const ctx = $('agent_context').item.json;
const offered = ctx.offered_slot_ids || [];
let clsCat = 'UNCLEAR';
try { clsCat = (JSON.parse($('Classify intent (Groq 8B)').item.json.choices[0].message.content).category || 'UNCLEAR').toUpperCase(); } catch (e) {}

// 1) Did they pick one of the offered slots?
let slot_id = parsed.slot_id || null;
if (slot_id && offered.indexOf(slot_id) === -1) slot_id = null;
// Only trust the generic accept fallback when Match choice (8B) itself found
// nothing else going on -- it must never override an explicit signal that this
// was NOT a plain acceptance (other_time/decline), or a smaller, less-informed
// classifier can force a wrong booking. Reproduced live: "gostaria que fosse
// com o Dr sousa" -> Match choice correctly said other_time:true, slot_id:null,
// but the generic classifier's ACCEPT tag (misread as agreement) overrode it
// and booked the wrong doctor with zero confirmation.
const matchWasExplicit = parsed.other_time === true || parsed.decline === true;
if (!slot_id && !matchWasExplicit && offered.length === 1 && clsCat === 'ACCEPT') slot_id = offered[0];
if (slot_id) return { json: { conversation_id: ctx.conversation_id, action: 'book', slot_id } };

// The day currently under discussion = date of the slots we last offered.
const offeredSlots = ctx.offered_slots || [];
const ctxDate = offeredSlots.length
  ? DateTime.fromISO(offeredSlots[0].start_time).setZone('Europe/Lisbon').toFormat('yyyy-MM-dd')
  : null;

const pm = (ctx.messages || []).filter(m => m.sender_type === 'patient');
const lastMsg = ((pm[pm.length - 1] || {}).body || '').toLowerCase();

// 2) A specific doctor mentioned by name (patient-initiated, e.g. "pode ser
// com o Dr Sousa?") -> retarget the search to that doctor for the same day
// already under discussion. Deterministic surname match against the real
// roster, never an LLM guess. This is a PATIENT request, so it becomes a
// permanent primary-doctor reassignment on booking (lock_doctor:true) --
// unlike an agent-offered substitute, which never locks. Reproduced live:
// this used to fall through to a generic reask that ignored the doctor
// question entirely.
const doctors = ctx.doctors || [];
let reqDoctorId = null;
for (const d of doctors) {
  const surname = d.name.trim().split(/\s+/).pop().toLowerCase();
  if (surname && lastMsg.includes(surname)) { reqDoctorId = d.id; break; }
}
if (reqDoctorId) {
  return { json: { conversation_id: ctx.conversation_id, action: 'retime',
    req_date: ctxDate || null, req_from: null, req_to: null,
    req_doctor_id: reqDoctorId, lock_doctor: true } };
}

// 3) Deterministic period words override the small model (reliable, closed set).
let ovFrom = null, ovTo = null, ovHit = false;
if (/fim do dia|fim da tarde|final do dia|final da tarde|ao fim da tarde/.test(lastMsg)) { ovFrom='16:00'; ovTo='19:00'; ovHit=true; }
else if (/almo[çc]o/.test(lastMsg)) { ovFrom='12:00'; ovTo='14:00'; ovHit=true; }
else if (/manh[ãa]/.test(lastMsg)) { ovFrom='08:00'; ovTo='13:00'; ovHit=true; }
else if (/\btarde\b/.test(lastMsg)) { ovFrom='13:00'; ovTo='19:00'; ovHit=true; }

// 4) A specific different time/day, or a period word -> targeted search.
//    Default the day to the one being discussed when the reply omits it.
const wantsOther = ovHit || (parsed.other_time === true && (parsed.date || parsed.from));
if (wantsOther) {
  return { json: { conversation_id: ctx.conversation_id, action: 'retime',
    req_date: parsed.date || ctxDate || null,
    req_from: ovHit ? ovFrom : (parsed.from || null),
    req_to:   ovHit ? ovTo   : (parsed.to   || null) } };
}

if (parsed.decline === true || clsCat === 'DECLINE') return { json: { conversation_id: ctx.conversation_id, action: 'decline' } };
return { json: { conversation_id: ctx.conversation_id, action: 'reask', message: 'Desculpe, não percebi bem. Diga-me só a hora ou o período que prefere, ou se quer manter como está.' } };

const res = $json; // book_slot result
const conv = $('Route match').item.json.conversation_id;
const p = $('agent_context').item.json.patient;
const isPlaceholder = /^Novo contacto/.test((p && p.name) || '');
const zone = 'Europe/Lisbon';
const fmt = (iso) => { const d = DateTime.fromISO(iso).setZone(zone); const today = DateTime.now().setZone(zone).startOf('day'); const diff = Math.round(d.startOf('day').diff(today,'days').days); const day = diff===0?'hoje':(diff===1?'amanhã':d.toFormat('dd/MM')); return day + ' às ' + d.toFormat('HH:mm'); };
let message;
if (res && res.status === 'booked') {
  message = 'Perfeito! Fica marcado para ' + fmt(res.start_time) + (res.doctor_name?(' com '+res.doctor_name):'') + '.';
  message += isPlaceholder ? ' Para completar o registo, pode dizer-me o seu nome?' : ' Até lá!';
} else {
  message = 'Peço desculpa, essa vaga já foi ocupada entretanto. Pode escolher outra das opções?';
}
return { json: { conversation_id: conv, message } };

