const body = ($('agent_inbound_batch').item.json.joined_body || '').trim();
const ctx = $('agent_context').item.json;
// Tokenize on non-letters so STOP/START are recognized as standalone words
// anywhere in the message (RGPD; also "nao posso, STOP" = decline + opt-out).
const tokens = body.toUpperCase().split(/[^A-ZÁÀÂÃÉÊÍÓÔÕÚÜÇ]+/).filter(Boolean);
const STOP  = ['STOP','PARAR','PARE','SAIR','REMOVER','CHEGA'];
const START = ['START','ATIVAR','SUBSCREVER','RETOMAR','INICIAR'];
let action = 'continue';
// STOP wins over START if both appear.
if (tokens.some(t => STOP.includes(t))) action = 'opt_out';
else if (tokens.some(t => START.includes(t))) action = 'opt_in';
return { json: { action, conversation_id: ctx.conversation_id } };

