const system = 'És um assistente que regista o nome do paciente. Este contacto ainda não tem nome. Se o paciente indicar o SEU nome (ex.: "chamo-me João Silva", "sou a Maria Santos", "o meu nome é ..."), devolve-o com maiúsculas iniciais. Se não indicar um nome, ou se tiveres dúvida, devolve null. Nunca uses o nome do médico nem inventes. Devolve JSON estrito {"name":"Nome Apelido"|null}.';
return { json: { conversation_id: conv, system_prompt: system, user_prompt: body } };

const parsed = JSON.parse($json.choices[0].message.content);
