const dayWord=(iso)=>{const d=DateTime.fromISO(iso).setZone(zone).startOf('day');const t=DateTime.now().setZone(zone).startOf('day');const diff=Math.round(d.diff(t,'days').days);return diff===0?'hoje':(diff===1?'amanhã':DateTime.fromISO(iso).setZone(zone).toFormat('dd/MM'));};
const fmt=(iso)=>dayWord(iso)+' às '+fmtTime(iso);
if (!res || res.status !== 'options' || !Array.isArray(res.slots) || res.slots.length === 0) {
  return { json: { conversation_id: conv, action: 'escalate', message: 'Peço desculpa, para essa altura não tenho vaga disponível de momento. Vou pedir à receção que veja outras opções consigo.', reason: 'Paciente pediu um horário sem vaga disponível' } };
}
const clinic = ctx.clinic_name || 'a clínica';
const patient = (ctx.patient && ctx.patient.name) || '';
const firstName = (patient && !/^Novo contacto/.test(patient)) ? patient.split(' ')[0] : '';
const single = res.slots.length === 1;
let facts;
if (res.requested && single) {
  const s=res.slots[0];
  facts = res.exact
    ? ('O paciente pediu as '+res.requested+' e HÁ vaga EXATAMENTE a essa hora: '+fmt(s.start_time)+(s.doctor_name?(' com '+s.doctor_name):'')+'. É a hora que ele pediu, NÃO uma aproximação. Objetivo: confirmar com simpatia que temos vaga à hora que pediu e perguntar se pode ser.')
    : ('O paciente pediu por volta das '+res.requested+', mas não há vaga a essa hora exata. A vaga livre mais próxima é '+fmt(s.start_time)+(s.doctor_name?(' com '+s.doctor_name):'')+'. Objetivo: dizer com simpatia que a hora pedida não está livre e propor esta, a mais próxima.');
} else {
  facts = 'Vaga(s) para a altura que o paciente pediu (reais, use tal e qual): '
    + res.slots.map(s => fmt(s.start_time)+(s.doctor_name?(' com '+s.doctor_name):'')).join('; ')
    + '. Objetivo: dizer de forma simpática que tem esta(s) vaga(s) e perguntar se lhe convém.';
}
const closeRule = single
  ? 'Há apenas UMA vaga: termine com uma pergunta natural de confirmação (ex.: "fica-lhe bem?", "pode ser?", "confirmo?"). NÃO pergunte "qual prefere" nem "qual lhe dá mais jeito". '
  : 'Há várias vagas: convide a escolher de forma natural (ex.: "qual lhe dá mais jeito?", "qual prefere?"). ';
const system = 'É rececionista da '+clinic+', em Portugal, e escreve como uma pessoa real: cordial, natural e breve. '
  + 'Português europeu formal ("você"), ou inglês se o paciente escreveu em inglês. Nunca se apresenta nem inventa nomes. '
  + (firstName ? ('Trate o paciente por "'+firstName+'". ') : '')
  + 'Escreva UMA mensagem curta em linguagem corrida (NUNCA use listas numeradas, "1)", "2)", nem bullets). '
  + closeRule
  + 'Não peça um formato rígido tipo "responda SIM ou NÃO" nem para responder com um número. '
  + 'Se os factos disserem que há vaga À HORA pedida, confirme que é exatamente essa hora; NUNCA escreva "perto", "próximo", "por volta" nem "aproximado". Só fale numa vaga "mais próxima" se os factos disserem que a hora pedida NÃO está disponível. '
  + 'REGRA ABSOLUTA: copie horas, datas e nomes EXATAMENTE como aparecem nos factos; nunca invente nem altere um número. '
  + 'NÃO escreva nenhuma linha sobre STOP nem sobre cancelar subscrição; isso é acrescentado automaticamente quando necessário. '
  + 'Responda APENAS com o texto da mensagem.';
return { json: { conversation_id: conv, action: 'humanize', system_prompt: system, user_prompt: facts } };

