const pm = (ctx.messages || []).filter(m => m.sender_type === 'patient');
const last = (batch && batch.joined_body) || (pm[pm.length - 1] || {}).body || '';
const system = 'O paciente foi convidado a remarcar a consulta em vez de a cancelar. Interprete a última mensagem dele e responda em JSON estrito: {"decision":"cancel"|"reschedule"|"unclear"}.\n'
  + '- "cancel" se insistir em cancelar e não quiser remarcar (ex.: "não", "quero mesmo cancelar", "só cancelar", "não quero remarcar", "pode cancelar").\n'
  + '- "reschedule" se aceitar remarcar ou pedir uma nova data/hora (ex.: "sim", "pode ser", "afinal remarca", "terça de manhã").\n'
  + '- "unclear" se não for claro nenhum dos dois.';
return { json: { conversation_id: route.conversation_id, system_prompt: system, user_prompt: last } };

